import { renderHtmlPdf } from "@/lib/htmlPdf";
import { orgData, rawB64, reportToTechDoc, usablePhotos } from "@/lib/docData";
import { logoDataUrl } from "@/lib/logo";

// Render a Technical Report (TR01) to a PDF Buffer using the HTML document
// template + headless Chromium — the single source of truth for the design.
// The QR image is generated by the caller (same summary text as before) and
// passed in as a data URL; site photos are injected as p1, p2, … assets that
// the template references by the `src` keys reportToTechDoc assigns.
export async function renderTechReportPdf(report, qrDataUrl) {
  const assets = { logo: rawB64(logoDataUrl()), qr: rawB64(qrDataUrl) };
  usablePhotos(report).forEach((p, i) => {
    assets[`p${i + 1}`] = rawB64(p.dataUrl);
  });
  return renderHtmlPdf("technical-report", {
    __QSL_ASSETS__: assets,
    __QSL_ORG__: orgData(),
    __QSL_REPORT__: reportToTechDoc(report),
  });
}
